module.exports = {
  LOCAL_PROFILE_VERSION,
  DEFAULT_PROFILE_ID,
  DEFAULT_PROFILE_NAME,
  validProfileId,
  normalizeProfileName,
  normalizeProfile,
  emptyLocalProfiles,
  readLocalProfiles,
  addLocalProfile,
  renameLocalProfile,
  removeLocalProfile,
};

